window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[79]={"id":"079","numero":79,"titre":"Addictions comportementales","objectifs":[{"id":"79-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’addiction comportementale","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">addictions comportementales</span></strong> se développent à partir de <span class=\"kw-clinique\">comportements ayant pour fonction de procurer du plaisir ou de soulager un malaise intérieur</span>. Le caractère addictif ne tient <strong>pas</strong> à la fréquence du comportement mais à trois éléments :</p>\n      <ul>\n        <li><strong>Perte de contrôle</strong> sur le comportement.</li>\n        <li><strong>Poursuite</strong> du comportement <span class=\"kw-alerte\">malgré des conséquences négatives</span>.</li>\n        <li>Présence d’un <strong><span class=\"kw-def\">craving</span></strong> — envies impérieuses de réaliser le comportement.</li>\n      </ul>\n      <p>Deux addictions comportementales sont <strong>officiellement reconnues</strong> dans <span class=\"kw-clinique\">les</span> classifications diagnostiques internationales :</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Statut nosographique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Jeu d’argent pathologique</span></td><td><em>Gambling disorder</em> — déjà intégré dans la <span class=\"kw-def\">CIM-10</span>. Addiction aux jeux de hasard et d’argent (grattage, <span class=\"kw-alerte\">tirage</span>, paris hippiques/sportifs, poker).</td></tr>\n          <tr><td><span class=\"kw-etio\">Trouble du jeu vidéo</span></td><td>Prochainement intégré dans la <span class=\"kw-def\">CIM-11</span>. Addiction aux jeux vidéo, en ligne ou hors ligne.</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> mécanismes de l’addiction comportementale <strong>partagent les bases physiopathologiques</strong> des <span class=\"kw-etio\">troubles liés à l’usage de substances</span> — le principal système impliqué étant le <strong><span class=\"kw-etio\">système dopaminergique de la récompense</span></strong> :</p>\n      <ul>\n        <li><strong>Recherche de plaisir :</strong> le comportement active le circuit de la récompense (<span class=\"kw-bio\">dopamine</span>, <span class=\"kw-clinique\">noyau accumbens</span>) ; sa répétition crée un <span class=\"kw-etio\">conditionnement pavlovien</span>, puis une décharge de <span class=\"kw-ttt\">dopamine</span> <strong>par anticipation</strong>.</li>\n        <li><strong>État émotionnel négatif :</strong> la <span class=\"kw-ttt\">dopamine</span> libérée diminue progressivement, le circuit devient moins sensible ; l’amygdale rend le sujet plus stressé et envahi d’émotions négatives (<span class=\"kw-clinique\">dysphorie</span>). Le comportement n’est plus réalisé pour le plaisir mais pour <strong>soulager la dysphorie</strong>.</li>\n        <li><strong>Perte de contrôle :</strong> altération du <span class=\"kw-clinique\">cortex préfrontal</span> (autorégulation, prise de décision) ; <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">cravings</span> expliquent les rechutes répétées, même lorsque le désir d’arrêter est sincère.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 77 — Addiction aux psychotropes · 78 — Addication aux drogues</em></p>","frequence":0},{"id":"79-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence du jeu d’argent pathologique","contenu":"<p>Données épidémiologiques françaises du <strong><span class=\"kw-etio\">jeu d’argent pathologique</span></strong> :</p>\n      <ul>\n        <li>Jeu à risque : <span class=\"kw-chiffre\">2,1 %</span> de la population.</li>\n        <li>Joueurs excessifs : <span class=\"kw-chiffre\">0,8 %</span>.</li>\n        <li>Soit près de <span class=\"kw-chiffre\">3 %</span> de la population en incluant <span class=\"kw-clinique\">les</span> joueurs à risque ou modérés.</li>\n      </ul>\n      <p>La pratique des jeux de hasard et d’argent (JHA) est <strong><span class=\"kw-ci\">interdite</span> aux <span class=\"kw-chiffre\">moins de 18 ans</span></strong>. Pourtant :</p>\n      <ul>\n        <li>La <span class=\"kw-def\">prévalence</span> du jeu d’argent pathologique chez <span class=\"kw-clinique\">les</span> <strong>mineurs</strong> est <span class=\"kw-chiffre\">2 à 3 fois</span> plus importante que chez les adultes.</li>\n        <li>Environ <span class=\"kw-chiffre\">1/3 des mineurs</span> ont déjà joué à un JHA avant <span class=\"kw-chiffre\">18 ans</span>.</li>\n        <li><strong><span class=\"kw-etio\">Adolescence</span></strong> et <strong><span class=\"kw-etio\">vieillesse</span></strong> sont des <span class=\"kw-def\">facteurs de risque</span>.</li>\n      </ul>\n      <p>Sex-ratio : <strong>prédominance masculine</strong>.</p>","frequence":0},{"id":"79-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque, l’évolution, le pronostic","contenu":"<p><span class=\"kw-clinique\">Les</span> addictions comportementales sont d’<strong>origine multifactorielle</strong> — <span class=\"kw-def\">modèle bio-psycho-social</span>. Les <span class=\"kw-def\">facteurs de risque</span> du jeu d’argent pathologique se répartissent en trois domaines :</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Facteurs de risque</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Individu</strong></td><td>\n            <span class=\"kw-etio\">Sexe masculin</span> ; précocité ; adolescence/vieillesse<br>\n            Mauvaise estime de soi ; défaut d’assertivité ; difficulté à résoudre <span class=\"kw-clinique\">les</span> problèmes<br>\n            <span class=\"kw-etio\">Impulsivité</span> ; recherche de sensations et de nouveauté<br>\n            Événements de vie, traumatismes ; <span class=\"kw-def\">comorbidités</span> (psychiatriques, addictives, TDAH)<br>\n            Altération des processus de décision et d’auto-contrôle ; <span class=\"kw-etio\">vulnérabilité génétique</span> ; médicaments dopaminergiques\n          </td></tr>\n          <tr><td><strong>Contexte socio-culturel</strong></td><td>\n            Normes familiales et culturelles ; apprentissage social<br>\n            Bas niveau de support social, d’éducation et de revenus<br>\n            <span class=\"kw-etio\">Accessibilité des JHA</span> et caractéristiques situationnelles\n          </td></tr>\n          <tr><td><strong>Objet de l’addiction</strong></td><td>\n            Type de jeu : caractéristiques structurelles<br>\n            Support de jeu : <span class=\"kw-etio\">Internet</span><br>\n            Distorsions cognitives\n          </td></tr>\n        </tbody>\n      </table>\n      <p>Le <strong>parcours du joueur pathologique</strong> typique comporte des phases successives :</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Phase de gain</span></td><td>Souvent initiée par un gain important (« <em>big win</em> ») ; le jeu est agréable. Le joueur interprète peu à peu ses gains comme le résultat de son <strong>habileté</strong>, et non du hasard.</td></tr>\n          <tr><td><span class=\"kw-def\">Phase de pertes</span></td><td><span class=\"kw-clinique\">Les</span> pertes poussent à rejouer pour « se refaire » (« <em>chasing</em> »). Les <span class=\"kw-clinique\">difficultés financières</span> apparaissent, minimisées par un <strong>optimisme irrationnel</strong>.</td></tr>\n          <tr><td><span class=\"kw-def\">Phase de désespoir</span></td><td>Dommages importants ; le sujet est à <span class=\"kw-alerte\">fort risque suicidaire</span> (avec ou sans <span class=\"kw-etio\">épisode dépressif caractérisé</span>).</td></tr>\n          <tr><td><span class=\"kw-def\">Phase d’abandon</span><br><em>(selon certains auteurs)</em></td><td>Le joueur abandonne ses fantasmes de gains et de réussite (deuil du gain) ; seul le fait de jouer compte.</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Évolution</span> et <span class=\"kw-def\">pronostic</span>.</strong> En l’absence de prise en charge, le jeu d’argent pathologique expose à un <span class=\"kw-alerte\">risque élevé de rechute</span>. La difficulté de la PEC tient au faible pourcentage de malades qui demandent des soins — <span class=\"kw-chiffre\">10 à 20 %</span> — avec des soins débutés plusieurs années après le début de la conduite et un taux de perdus de vue de <span class=\"kw-chiffre\">15 à 50 %</span>.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Évaluer <strong>systématiquement le <span class=\"kw-alerte\">risque suicidaire</span></strong> : il peut être élevé et n’est <strong>pas systématiquement lié</strong> à un <span class=\"kw-etio\">épisode dépressif caractérisé</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble anxieux</em></p>","frequence":0},{"id":"79-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux types d’addiction comportementale","contenu":"<p>On distingue deux addictions comportementales <strong>officiellement reconnues</strong> et plusieurs types <strong>non encore consensuels</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Jeu d’argent pathologique</span></strong> (CIM-10).</li>\n        <li><strong><span class=\"kw-etio\">Trouble du jeu vidéo</span></strong> (CIM-11).</li>\n        <li>Autres types : <span class=\"kw-etio\">addiction sexuelle</span>, <span class=\"kw-etio\">achats compulsifs</span>, <span class=\"kw-etio\">addiction à l’exercice physique</span>.</li>\n        <li>L’addiction à Internet est <strong>encore discutée</strong> — considérée à part, non traitée ici.</li>\n      </ul>\n      <p><strong>Jeu d’argent pathologique.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">jeux de hasard et d’argent</span> (JHA) supposent une mise <strong>irréversible</strong> d’un bien, dont l’issue dépend partiellement ou totalement du hasard :</p>\n      <ul>\n        <li>Jeux de hasard purs : loteries, grattage, machines à sous, roulette.</li>\n        <li>Jeux de hasard avec quasi-adresse : paris sportifs et hippiques, black jack.</li>\n        <li>Jeux de hasard et d’adresse sans gain durable possible : poker.</li>\n      </ul>\n      <p><strong>Diagnostic de certitude</strong> du jeu d’argent pathologique : présence d’<strong><span class=\"kw-chiffre\">au moins 4</span></strong> des manifestations suivantes <strong>au cours de la dernière année</strong> :</p>\n      <ul>\n        <li>Besoin de jouer avec des <strong>sommes d’argent croissantes</strong> pour atteindre l’excitation désirée.</li>\n        <li><span class=\"kw-clinique\">Agitation</span> ou <span class=\"kw-clinique\">irritabilité</span> lors des tentatives de <span class=\"kw-ttt\">réduction</span> ou d’arrêt.</li>\n        <li>Efforts répétés mais <strong>infructueux</strong> pour contrôler, réduire ou arrêter.</li>\n        <li><span class=\"kw-clinique\">Préoccupations</span> par le jeu (remémoration, prévision, moyens de se procurer de l’argent).</li>\n        <li>Joue souvent lors de sentiments de souffrance ou de mal-être (impuissance, culpabilité, anxiété, <span class=\"kw-def\">dépression</span>).</li>\n        <li>Retourne souvent jouer après une perte pour « se refaire » (« <em>chasing</em> »).</li>\n        <li><strong>Ment</strong> pour dissimuler l’ampleur réelle de ses habitudes de jeu.</li>\n        <li>Met en danger ou a perdu une relation affective, un emploi ou des études à cause du jeu.</li>\n        <li>Compte sur <span class=\"kw-clinique\">les</span> autres pour obtenir de l’argent et se sortir de situations financières désespérées.</li>\n      </ul>\n      <p><strong>Trouble du jeu vidéo</strong> — définition <span class=\"kw-def\">CIM-11</span> : tendance comportementale aux jeux numériques persistante ou récurrente, caractérisée par :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Contrôle altéré</span> sur <span class=\"kw-clinique\">les</span> jeux (apparition, fréquence, intensité, durée, contexte).</li>\n        <li><strong>Priorité croissante</strong> donnée aux jeux, au point de dominer <span class=\"kw-clinique\">les</span> autres aspects de la vie.</li>\n        <li>Poursuite ou escalade de la pratique malgré l’occurrence de <span class=\"kw-alerte\">conséquences négatives</span>.</li>\n        <li>Durée généralement <span class=\"kw-chiffre\">≥ 12 mois</span> (parfois plus courte si tous <span class=\"kw-clinique\">les</span> critères sont réunis et les symptômes sévères).</li>\n      </ul>\n      <p><strong>Comparatif des autres addictions comportementales :</strong></p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Trouble du jeu vidéo</th><th>Addiction sexuelle</th><th>Achats compulsifs</th><th>Addiction à l’exercice physique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td><span class=\"kw-chiffre\">1 à 3 %</span></td><td><span class=\"kw-chiffre\">0,5 à 5 %</span></td><td><span class=\"kw-chiffre\">5 %</span></td><td><span class=\"kw-chiffre\">3 %</span></td></tr>\n          <tr><td><strong>Sex-ratio</strong></td><td>Masculin (<span class=\"kw-chiffre\">80 %</span>)</td><td>Masculin (<span class=\"kw-chiffre\">80 %</span>)</td><td>Féminin (<span class=\"kw-chiffre\">90 %</span>)</td><td>Féminin (<span class=\"kw-chiffre\">66 %</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Comorbidités</span> à rechercher</strong></td><td>Trouble délirant ; TDAH</td><td>Chemsex et slam</td><td><span class=\"kw-etio\">Trouble bipolaire</span> ; <span class=\"kw-etio\">boulimie</span></td><td>Troubles des conduites alimentaires (<span class=\"kw-etio\">anorexie mentale</span>, <span class=\"kw-etio\">boulimie</span> nerveuse)</td></tr>\n          <tr><td><strong>Diagnostics différentiels</strong></td><td>—</td><td>Paraphilies ; hypersexualité <span class=\"kw-etio\">iatrogène</span> (agonistes dopaminergiques, ex. maladie de Parkinson) ; hypersexualité neurologique (lésions frontales/temporales, <span class=\"kw-etio\">épilepsie</span>)</td><td><span class=\"kw-etio\">TOC</span></td><td>Hyperactivité liée à un <span class=\"kw-etio\">TDAH</span></td></tr>\n          <tr><td><strong>PEC spécifique</strong></td><td>Thérapie familiale ; accompagnement de l’entourage</td><td><span class=\"kw-ttt\">Antidépresseurs ISRS</span> (hors AMM) ; rechercher des <span class=\"kw-clinique\">IST</span></td><td>Mesures de protection possibles (sauvegarde de justice, curatelle, tutelle)</td><td>cf. troubles des conduites alimentaires</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Chemsex et slam.</strong> Le <strong>chemsex</strong> est l’usage de substances psychoactives en contexte sexuel (surtout cathinones de synthèse, méthamphétamine, gammabutyrolactone) — risque d’addiction au produit concomitante de l’addiction au sexe. Le <strong>slam</strong> désigne l’injection intraveineuse de ces substances. À rechercher dans l’addiction sexuelle.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 71 — Troubles conduite alimentaire · 106 — Parkinson</em></p>","frequence":0},{"id":"79-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les comorbidités psychiatriques et addictives","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">comorbidités</span> sont présentes dans <strong><span class=\"kw-chiffre\">50 à 75 %</span></strong> des addictions comportementales — d’autant plus fréquentes en cas de <strong>co-addictions</strong>. Elles constituent <strong>souvent le motif initial de consultation</strong>.</p>\n      <p><strong><span class=\"kw-def\">Comorbidités</span> psychiatriques et addictives à connaître :</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">TDAH</span></strong> — trouble déficit de l’attention avec ou sans hyperactivité.</li>\n        <li><span class=\"kw-etio\">Troubles de l’humeur</span>.</li>\n        <li><span class=\"kw-etio\">Troubles anxieux</span>.</li>\n        <li><span class=\"kw-etio\">Troubles de la personnalité</span>.</li>\n        <li><span class=\"kw-etio\">Troubles de l’usage de substances</span> — <span class=\"kw-etio\">tabac</span> et <span class=\"kw-etio\">alcool</span> surtout.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Diagnostic différentiel</span>.</strong> <span class=\"kw-alerte\">Épisode maniaque ou hypomaniaque</span> : si l’addiction comportementale survient <strong>exclusivement</strong> durant ces épisodes, le diagnostic d’addiction comportementale n’est pas retenu.\n      </div>\n      <p><strong><span class=\"kw-def\">Comorbidités</span> plus spécifiques selon le type d’addiction :</strong></p>\n      <table >\n        <thead><tr><th>Type d’addiction</th><th>Comorbidités à rechercher en priorité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Trouble du jeu vidéo</span></td><td>Trouble délirant ; TDAH</td></tr>\n          <tr><td><span class=\"kw-etio\">Addiction sexuelle</span></td><td>Chemsex et slam</td></tr>\n          <tr><td><span class=\"kw-etio\">Achats compulsifs</span></td><td><span class=\"kw-etio\">Trouble bipolaire</span> ; <span class=\"kw-etio\">boulimie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Addiction à l’exercice physique</span></td><td>Troubles des conduites alimentaires (<span class=\"kw-etio\">anorexie mentale</span>, <span class=\"kw-etio\">boulimie</span> nerveuse)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 55 — Développement psychomoteur · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble anxieux · 353 — Risque et conduite suicidaire</em></p>","frequence":0},{"id":"79-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes et les objectifs de la prise en charge","contenu":"<p><span class=\"kw-clinique\">Les</span> principes ci-dessous concernent le <strong>jeu d’argent pathologique</strong> mais valent pour les <strong>autres addictions comportementales</strong>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Principes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Objectif</strong></td><td>\n            À long terme : <strong>retour durable à une pratique contrôlée</strong> du jeu.<br>\n            Possible soit par un <strong>arrêt complet</strong>, soit par une <strong>diminution de la fréquence</strong> de jeu.<br>\n            Le <span class=\"kw-alerte\">choix de l’objectif revient au patient</span>.\n          </td></tr>\n          <tr><td><strong>Orientation</strong></td><td>\n            Préférentiellement <strong><span class=\"kw-ttt\">ambulatoire</span></strong>.<br>\n            <span class=\"kw-clinique\">Hospitalisation en 2nde intention</span> : échec, troubles associés, ajustement thérapeutique.\n          </td></tr>\n          <tr><td><strong>Psychothérapie</strong></td><td>\n            <strong><span class=\"kw-ttt\">Entretien motivationnel</span></strong> et <strong><span class=\"kw-ttt\">thérapies cognitivo-comportementales</span></strong> (individuelles ou en groupe) : efficacité démontrée.<br>\n            Associations de joueurs (<em><span class=\"kw-ttt\">Gamblers Anonymous</span></em>), forums, soutien de pairs, manuels de self-help.<br>\n            <strong>Associer l’entourage</strong> à la prise en charge (<span class=\"kw-ttt\">consultations conjointes</span>), souvent dans l’incompréhension.\n          </td></tr>\n          <tr><td><strong>Pharmacothérapie</strong></td><td>\n            <span class=\"kw-ci\">Aucun traitement médicamenteux n’a d’AMM</span> pour ce trouble.<br>\n            Un traitement n’est indiqué que pour <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">comorbidités</span> psychiatriques</strong> (ex. <span class=\"kw-ttt\">ISRS</span> hors AMM dans l’addiction sexuelle).\n          </td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques</em></p>","frequence":1},{"id":"79-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prévention primaire et secondaire","contenu":"<p>La prévention du jeu d’argent pathologique s’articule en deux niveaux distincts :</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévention primaire</span></strong></td><td>\n            Repose sur l’<strong>information et l’<span class=\"kw-ttt\">éducation des joueurs</span></strong>.<br>\n            Doit impliquer <span class=\"kw-clinique\">les</span> responsables de casinos et les sites de jeux en ligne.\n          </td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prévention secondaire</span></strong></td><td>\n            Repose sur la <strong><span class=\"kw-ttt\">formation de personnel</span></strong> capable de <span class=\"kw-clinique\">repérer directement</span> <span class=\"kw-clinique\">les</span> comportements évocateurs de jeu d’argent pathologique :<br>\n            <strong><span class=\"kw-def\">Personnel spécialisé</span> :</strong> <span class=\"kw-ttt\">psychologues</span><br>\n            <strong><span class=\"kw-def\">Personnel non spécialisé</span> :</strong> croupiers, personnel de salle\n          </td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"79-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les mesures associées","contenu":"<p>L’<strong>accompagnement social</strong> vise à limiter ou éviter <span class=\"kw-clinique\">les</span> problèmes de dettes — il relève de la <strong><span class=\"kw-def\">prévention tertiaire</span></strong>. Il repose sur trois leviers :</p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Accompagnement bancaire</strong></td><td>Mesures d’accompagnement auprès des établissements bancaires.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Interdiction de jeu</span></strong></td><td>\n            Inscription sur la <strong><span class=\"kw-def\">liste nationale des interdits de jeu</span></strong>.<br>\n            <strong><span class=\"kw-clinique\">Auto-exclusion</span> :</strong> le patient peut faire lui-même une démarche d’interdiction d’accès auprès des opérateurs de jeux ou des casinos.<br>\n            En France, casinos et sites internet légaux ont l’<strong>obl<span class=\"kw-chiffre\">iga</span>tion de proposer</strong> ces mesures.\n          </td></tr>\n          <tr><td><strong>Protection des biens</strong></td><td>\n            <strong><span class=\"kw-def\">Sauvegarde de justice</span> :</strong> possible <strong>en <span class=\"kw-alerte\">urgence</span></strong>.<br>\n            <strong><span class=\"kw-def\">Tutelle</span> ou <span class=\"kw-def\">curatelle</span> :</strong> <span class=\"kw-alerte\">jamais en urgence</span>.\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant à connaître.</strong> Seule la <strong>sauvegarde de justice</strong> peut être mise en place <strong>en <span class=\"kw-alerte\">urgence</span></strong> ; la <strong>tutelle</strong> et la <strong>curatelle</strong> ne sont <span class=\"kw-alerte\">jamais</span> instaurées en urgence.\n      </div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Risque suicidaire :</strong> à <span class=\"kw-alerte\">évaluer systématiquement</span>, il peut être <span class=\"kw-alerte\">élevé</span> et n'est pas systématiquement lié à un <span class=\"kw-etio\">épisode dépressif caractérisé</span><br><strong>Phase de désespoir :</strong> <span class=\"kw-def\">stade</span> des dommages importants exposant à un <span class=\"kw-alerte\">fort risque suicidaire</span><br><strong>Protection des biens :</strong> <span class=\"kw-ttt\">sauvegarde de justice</span> possible <span class=\"kw-chiffre\">en urgence</span> ; <span class=\"kw-ttt\">tutelle</span>/<span class=\"kw-ttt\">curatelle</span> <span class=\"kw-alerte\">jamais en urgence</span></p>","hospit":"<p><strong>1re intention :</strong> prise en charge <span class=\"kw-ttt\">ambulatoire</span> préférentielle<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> en <span class=\"kw-chiffre\">2nde intention</span> — <span class=\"kw-etio\">échec</span> ambulatoire, <span class=\"kw-etio\">troubles associés</span> ou besoin d'<span class=\"kw-ttt\">ajustement thérapeutique</span><br><strong>Entourage :</strong> à <span class=\"kw-ttt\">associer à la prise en charge</span> (consultations conjointes)</p>","redflags":"<ul><li><span class=\"kw-alerte\">Risque suicidaire</span> élevé, à <span class=\"kw-alerte\">évaluer systématiquement</span> (non systématiquement lié à un <span class=\"kw-etio\">EDC</span>)</li><li><span class=\"kw-etio\">Phase de désespoir</span> : dommages importants, risque suicidaire majeur</li><li><span class=\"kw-alerte\">Difficultés financières</span> majeures et <span class=\"kw-etio\">endettement</span></li><li>Conséquences <span class=\"kw-etio\">légales/judiciaires</span> (vols, escroqueries)</li><li><span class=\"kw-etio\">Comorbidités</span> psychiatriques et addictives, présentes dans <span class=\"kw-chiffre\">50-75%</span> des cas</li><li>Faible recours aux soins (<span class=\"kw-chiffre\">10 à 20%</span>) et <span class=\"kw-chiffre\">15 à 50%</span> de perdus de vue</li></ul>","principes":"<p>Prise en charge <span class=\"kw-ttt\">multimodale</span>, identique pour toutes <span class=\"kw-clinique\">les</span> addictions comportementales ; objectif : <span class=\"kw-ttt\">retour durable à une pratique contrôlée</span>.</p><p><strong>🎯 Objectifs</strong></p><ul><li>Objectif à long terme : <span class=\"kw-ttt\">retour durable à une pratique contrôlée</span></li><li>Soit par un <span class=\"kw-ttt\">arrêt complet</span>, soit par une <span class=\"kw-ttt\">diminution de la fréquence</span> de jeu</li><li>Le <span class=\"kw-ttt\">choix de l'objectif revient au patient</span></li></ul><p><strong>🗣️ Psychothérapie (1re intention)</strong></p><ul><li><span class=\"kw-ttt\">Entretien motivationnel</span> et <span class=\"kw-ttt\">thérapies cognitivo-comportementales</span> (individuelles ou en groupe), efficacité prouvée</li><li><span class=\"kw-ttt\">Groupes de soutien par les pairs</span> (ex Gamblers Anonymous), forums, manuels de self-help</li><li><span class=\"kw-ttt\">Associer l'entourage</span> via des consultations conjointes</li></ul><p><strong>💊 Pharmacothérapie</strong></p><ul><li><span class=\"kw-ci\">Aucun traitement médicamenteux n'a d'AMM</span> dans le jeu d'argent pathologique</li><li>Médicament indiqué uniquement <span class=\"kw-ttt\">si comorbidités psychiatriques</span> (ex <span class=\"kw-ttt\">ISRS</span> hors AMM dans l'addiction sexuelle)</li></ul><p><strong>🏦 Accompagnement social (<span class=\"kw-def\">prévention tertiaire</span>)</strong></p><ul><li><span class=\"kw-ttt\">Mesures d'accompagnement bancaires</span> pour limiter l'endettement</li><li><span class=\"kw-ttt\">Interdiction de jeu</span> : auto-exclusion, inscription sur la liste nationale des interdits de jeu</li><li><span class=\"kw-ttt\">Sauvegarde de justice</span> (en <span class=\"kw-alerte\">urgence</span>), <span class=\"kw-ttt\">tutelle</span>/<span class=\"kw-ttt\">curatelle</span> (<span class=\"kw-alerte\">jamais en urgence</span>)</li></ul>","suivi":"<p><strong>Risque suicidaire :</strong> <span class=\"kw-def\">réévaluation</span> <span class=\"kw-alerte\">systématique</span> tout au long du <span class=\"kw-def\">suivi</span><br><strong>Rechute :</strong> <span class=\"kw-alerte\">risque élevé de rechute</span> sans prise en charge ; <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">cravings</span> expliquent les rechutes répétées<br><strong>Adhésion :</strong> <span class=\"kw-alerte\">risque élevé de perdus de vue</span> (<span class=\"kw-chiffre\">15 à 50%</span>), soins souvent débutés plusieurs années après le début<br><strong><span class=\"kw-def\">Comorbidités</span> :</strong> dépister troubles de l'humeur, anxieux, <span class=\"kw-etio\">TDAH</span>, troubles de l'usage de substances</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Trouble addictif comportemental confirmé — ≥4 manifestations sur la dernière année, perte de contrôle malgré les conséquences négatives, épisode maniaque/hypomaniaque éliminé","detail":"<h4>CAT — Jeu d'argent pathologique / addiction comportementale — Du trouble confirmé à l'orientation thérapeutique</h4>","branches":[{"to":"q-suicide","label":"Évaluer la gravité","color":"blue"}]},{"id":"q-suicide","kind":"decision","label":"Risque suicidaire élevé ou phase de désespoir ? — À évaluer systématiquement, non systématiquement lié à un EDC","branches":[{"to":"t-urgence","label":"Oui","color":"red"},{"to":"q-orientation","label":"Non","color":"green"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence psychiatrique — Mise en sécurité immédiate","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Évaluation systématique du risque suicidaire</span></li><li><span class=\"kw-ttt\">Hospitalisation</span> et mise en sécurité du patient</li></ul><h4>Protection</h4><ul><li><span class=\"kw-ttt\">Sauvegarde de justice</span> possible <span class=\"kw-chiffre\">en urgence</span> pour protéger <span class=\"kw-clinique\">les</span> biens</li><li><span class=\"kw-ttt\">Tutelle</span> ou <span class=\"kw-ttt\">curatelle</span> : <span class=\"kw-alerte\">jamais en urgence</span></li></ul>"},{"id":"q-orientation","kind":"decision","label":"Échec ambulatoire, troubles associés ou besoin d'ajustement thérapeutique ?","branches":[{"to":"t-ambu","label":"Non","color":"green"},{"to":"t-hospit","label":"Oui","color":"amber"}]},{"id":"t-ambu","kind":"terminal","label":"Prise en charge ambulatoire — 1re intention","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Entretien motivationnel</span> + <span class=\"kw-ttt\">thérapies cognitivo-comportementales</span> (individuelles ou en groupe)</li><li><span class=\"kw-ttt\">Groupes de soutien par les pairs</span> (ex Gamblers Anonymous) et <span class=\"kw-ttt\">accompagnement de l'entourage</span></li><li><span class=\"kw-ci\">Aucun médicament n'a d'AMM</span> ; pharmacothérapie <span class=\"kw-ttt\">indiquée si comorbidités psychiatriques</span></li></ul><h4>Objectif</h4><ul><li><span class=\"kw-ttt\">Retour durable à une pratique contrôlée</span> : <span class=\"kw-ttt\">arrêt complet</span> ou <span class=\"kw-ttt\">diminution de la fréquence</span></li><li>Le <span class=\"kw-ttt\">choix de l'objectif revient au patient</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Accompagnement social</span> : mesures bancaires, <span class=\"kw-ttt\">interdiction de jeu</span> (auto-exclusion, liste nationale des interdits de jeu)</li></ul>"},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation — 2nde intention","color":"amber","detail":"<h4>Conduite</h4><ul><li>Indiquée en cas d'<span class=\"kw-etio\">échec</span> de la prise en charge ambulatoire</li><li>Présence de <span class=\"kw-etio\">troubles associés</span> (<span class=\"kw-def\">comorbidités</span> psychiatriques/addictives)</li><li>Besoin d'<span class=\"kw-ttt\">ajustement thérapeutique</span></li></ul>"}]},"cards":[]};